import ITensors: SmallString, Tag, isint, isnull, IntChar

@testset "SmallString" begin
  @testset "ctors" begin
    s = SmallString()
    @test isnull(s)
  end

  @testset "setindex" begin
    s = SmallString()
    @test isnull(s)
    t = setindex(s, IntChar(1), 1)
    @test !isnull(t)
  end

  @testset "comparison" begin
    u = SmallString("1")
    t = SmallString("1")
    @test u == t
    t = SmallString("2")
    @test u < t
  end

  @testset "Convert to String" begin
    s = SmallString("abc")
    @test typeof(s) == SmallString

    sg = String(s)
    for n in 1:length(sg)
      @test sg[n] == convert(Char, s[n])
    end

    s = SmallString("")
    sg = String(s)
    @test sg == ""
  end

  @testset "isint" begin
    i = SmallString("123")
    @test isint(i) == true

    s = SmallString("abc")
    @test isint(s) == false

    # Test maximum length
    s = SmallString("12345678")
    @test isint(s) == true
  end

  @testset "isless" begin
    s1 = SmallString("ab")
    s2 = SmallString("xy")
    @test isless(s1, s2) == true
    @test isless(s2, s1) == false
    @test isless(s1, s1) == false
    @test isless(s2, s2) == false
  end

  @testset "show" begin
    t = Tag("")
    @test sprint(show, t) == ""

    t = Tag("Red")
    @test sprint(show, t) == "Red"

    # Make sure to test maximum length tag
    t = Tag("Electron")
    @test sprint(show, t) == "Electron"
  end
end

using ITensors, LinearAlgebra, Test
using ITensors.SiteTypes: has_fermion_string, op, siteind, siteinds, state

@testset "Physics Sites" begin
  N = 10

  @testset "Generic sites" for eltype in (Float32, Float64, ComplexF32, ComplexF64)
    d1, d2 = 3, 4
    i1, i2 = Index(d1), Index(d2)

    o = op("I", i1; eltype)
    @test o == itensor(Matrix(I, d1, d1), i1', dag(i1))
    @test Base.eltype(o) <: eltype

    o = op("Id", i1; eltype)
    @test o == itensor(Matrix(I, d1, d1), i1', dag(i1))
    @test Base.eltype(o) <: eltype

    o = op("F", i1; eltype)
    @test o == itensor(Matrix(I, d1, d1), i1', dag(i1))
    @test Base.eltype(o) <: eltype

    o = op("I", i1, i2; eltype)
    @test o == itensor(Matrix(I, d1 * d2, d1 * d2), i2', i1', dag(i2), dag(i1))
    @test Base.eltype(o) <: eltype

    o = op("Id", i1, i2; eltype)
    @test o == itensor(Matrix(I, d1 * d2, d1 * d2), i2', i1', dag(i2), dag(i1))
    @test Base.eltype(o) <: eltype

    U1 = op("RandomUnitary", i1)
    @test hassameinds(U1, (i1', i1))
    @test apply(transpose(dag(U1)), U1) ≈ itensor(Matrix(I, d1, d1), i1', dag(i1))

    U1 = op("randU", i1)
    @test hassameinds(U1, (i1', i1))
    @test apply(transpose(dag(U1)), U1) ≈ itensor(Matrix(I, d1, d1), i1', dag(i1))

    U12 = op("RandomUnitary", i1, i2)
    @test hassameinds(U12, (i1', i2', i1, i2))
    @test apply(transpose(dag(U12)), U12) ≈
      itensor(Matrix(I, d1 * d2, d1 * d2), i2', i1', dag(i2), dag(i1))
  end

